pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // caller must be the current owner (set in constructor to address(this))
        bool ok;
        bool ret = false;
        try c.setOwner(newOwner) returns (bool s) {
            ok = true;
            ret = s;
        } catch {
            ok = false;
        }
        assertTrue(ok && ret == c.owner() == false ? false : (ok && ret), "successful setOwner must return true and set owner");
    }
}

