pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address intermediary;

    function setUp() public { c = new C(); intermediary = address(new Intermediary()); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address ownerBefore = c.owner();
        // a non-owner intermediary contract attempts setOwner; tx.origin is set to the
        // real owner, so only the buggy tx.origin check would let it through
        vm.prank(intermediary, ownerBefore);
        bool ok;
        try Intermediary(intermediary).setOwnerOn(c, newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // rule: a non-owner caller can never change owner
        assertTrue(!ok && c.owner() == ownerBefore);
    }
}

contract Intermediary {
    function setOwnerOn(C c, address newOwner) external {
        c.setOwner(newOwner);
    }
}

